// D32 · Part 1~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_flow.ts   (서버는 임시 포트로 띄우고 브라우저 대신 같은 파일의 '가짜 브라우저'가 요청 · 마이크·인터넷 불필요)
//   서버가 웹 페이지를 내려 주고, '가짜 브라우저'(같은 파일)가 48 kHz 마이크 소리를 16 kHz 조각으로 바꿔 업로드 · 실시간 전송까지
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

class Resampler {
  // AudioWorklet의 PCMWorklet을 그대로 옮긴 것: 마이크 소리(48 kHz 등)를 128샘플 블록씩 받아 16 kHz · 16비트 · 320샘플(20 ms) 조각으로 낸다
  ratio: number; // 48000 → 3, 44100 → 2.75625
  frame: number;
  pos: number = 0; // 다음에 고를 위치
  prev: number = 0; // 앞 블록의 마지막 값
  buf: number[] = [];
  constructor(inRate: number, outRate: number = 16000, frame: number = 320) {
    this.ratio = inRate / outRate;
    this.frame = frame;
  }
  process(x: Float32Array): Int16Array[] {
    const frames: Int16Array[] = [];
    while (this.pos < x.length - 1) {
      const i = Math.floor(this.pos);
      const f = this.pos - i;
      const a = i < 0 ? this.prev : x[i];
      const b = i < 0 ? x[0] : x[i + 1];
      const v = a + (b - a) * f; // 선형 보간
      this.buf.push(Math.trunc(Math.max(-1, Math.min(1, v)) * 32767)); // -1 ~ 1 실수 → 16비트 정수
      if (this.buf.length === this.frame) {
        // 20 ms 모임 → 화면 스레드로
        frames.push(Int16Array.from(this.buf));
        this.buf = [];
      }
      this.pos += this.ratio;
    }
    this.pos -= x.length;
    this.prev = x[x.length - 1];
    return frames;
  }
}

function runWorklet(y: Float32Array, inRate: number, block: number = 128): Float32Array {
  // 소리 전체를 128샘플 블록으로 잘라 워클릿에 흘려 넣고, 나온 조각을 이어 붙인다
  const w = new Resampler(inRate);
  const out: number[] = [];
  for (let i = 0; i + block <= y.length; i += block) for (const f of w.process(y.subarray(i, i + block))) for (const v of f) out.push(v / 32767);
  return Float32Array.from(out);
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

type WsPeer = { onmessage: ((data: Buffer, isBinary: boolean) => void) | null; send: (data: string | Uint8Array) => void; close: () => void };

function serveWs(server: Server, path: string, handler: (ws: WsPeer) => void): void {
  // Node에는 WebSocket '서버'가 내장돼 있지 않아 HTTP Upgrade(101)와 프레임 읽기 · 쓰기를 직접 구현 (텍스트 · 바이너리만)
  server.on("upgrade", (req, socket) => {
    if (req.url !== path) {
      socket.destroy();
      return;
    }
    const accept = createHash("sha1").update(String(req.headers["sec-websocket-key"]) + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64");
    socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`);
    const ws: WsPeer = {
      onmessage: null,
      send(data) {
        const op = typeof data === "string" ? 1 : 2;
        const p = Buffer.from(data);
        const head = p.length < 126 ? Buffer.from([0x80 | op, p.length]) : Buffer.from([0x80 | op, 126, p.length >> 8, p.length & 255]);
        socket.write(Buffer.concat([head, p]));
      },
      close() {
        socket.end(Buffer.from([0x88, 0]));
      },
    };
    let buf = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        if (buf.length < 2) return;
        const opcode = buf[0] & 15;
        let len = buf[1] & 127;
        let off = 2;
        if (len === 126) {
          if (buf.length < 4) return;
          len = buf.readUInt16BE(2);
          off = 4;
        } else if (len === 127) {
          if (buf.length < 10) return;
          len = Number(buf.readBigUInt64BE(2));
          off = 10;
        }
        if (buf.length < off + 4 + len) return;
        const mask = buf.subarray(off, off + 4);
        const data = Buffer.from(buf.subarray(off + 4, off + 4 + len));
        for (let i = 0; i < len; i++) data[i] ^= mask[i % 4];
        buf = buf.subarray(off + 4 + len);
        if (opcode === 8) {
          socket.end();
          return;
        }
        if (opcode === 1 || opcode === 2) ws.onmessage?.(data, opcode === 2);
      }
    });
    socket.on("error", () => {});
    handler(ws);
  });
}

function wsConnect(host: string, path: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://${host}${path}`);
    ws.binaryType = "arraybuffer";
    ws.onopen = () => resolve(ws);
    ws.onerror = () => reject(new Error("WebSocket 연결 실패"));
  });
}

const LIVE_PAGE = "<button id=start>시작</button><script>new AudioWorkletNode(ctx, 'pcm-worklet'); new WebSocket(wsURL('ws/stt'));</script>";
const REC_PAGE = "<button id=start>녹음</button><script>new MediaRecorder(stream); new FormData();</script>";

const server = createServer(async (req, res) => {
  if (req.url === "/live" || req.url === "/rec") {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    return res.end(req.url === "/live" ? LIVE_PAGE : REC_PAGE);
  }
  if (req.method === "POST" && req.url === "/upload") {
    const f = await readFile(req);
    return f ? sendJson(res, 200, { text: hear(decodeWav(f.data)) }) : sendJson(res, 422, { detail: "file 칸이 없어요" });
  }
  sendJson(res, 404, { detail: "없는 주소" });
});

serveWs(server, "/ws/stt", (ws) => {
  const pcm: Buffer[] = [];
  ws.onmessage = (data, isBinary) => {
    if (isBinary) pcm.push(data);
    else if (data.toString() === "END") {
      // 대체 경로: 말 끝 판단(VAD) 대신 END 신호로 끊음
      const all = Buffer.concat(pcm);
      const y = new Float32Array(all.length >> 1);
      for (let i = 0; i < y.length; i++) y[i] = all.readInt16LE(i * 2) / 32768;
      ws.send(JSON.stringify({ type: "final", text: hear(y) }));
      ws.close();
    }
  };
});

async function main(): Promise<void> {
  const host = await listen(server);
  const base = `http://${host}`;
  const voice16 = say(["진료", "비용"]);
  const mic48 = Float32Array.from({ length: voice16.length * 3 }, (_, i) => {
    // 대체 경로: 48 kHz 마이크 소리를 합성 (16 kHz 소리를 선형으로 늘림)
    const p = i / 3;
    const k = Math.floor(p);
    return voice16[k] + ((voice16[Math.min(k + 1, voice16.length - 1)] - voice16[k]) * (p - k));
  });
  const pages = [await fetch(`${base}/rec`), await fetch(`${base}/live`)];
  const texts = await Promise.all(pages.map((p) => p.text()));
  const up = (await (await fetch(`${base}/upload`, { method: "POST", body: uploadForm(wavBytes(voice16)) })).json()) as { text: string };
  console.log("페이지:", pages.map((p, i) => [p.status, texts[i].includes("MediaRecorder") || texts[i].includes("AudioWorkletNode")]), "· 업로드 받아쓰기:", up.text);

  const worklet = new Resampler(48000); // 마이크(48 kHz) → 16 kHz PCM16 320샘플 조각
  const frames: Int16Array[] = [];
  for (let i = 0; i + 128 <= mic48.length; i += 128) frames.push(...worklet.process(mic48.subarray(i, i + 128)));
  const ws = await wsConnect(host, "/ws/stt");
  const final = new Promise<{ text: string }>((resolve) => (ws.onmessage = (e) => resolve(JSON.parse(String(e.data)))));
  for (const f of frames) ws.send(f);
  ws.send("END");
  const fin = await final;
  console.log(`48 kHz ${mic48.length.toLocaleString()}샘플 → 20 ms 조각 ${frames.length}개 (각 ${frames[0].byteLength}바이트) → 실시간 받아쓰기: ${fin.text}`);
  check(pages.every((p) => p.status === 200) && texts[0].includes("MediaRecorder") && texts[1].includes("AudioWorkletNode"), "서버가 두 웹 페이지를 내려 줘요.");
  check(up.text === "진료 비용" && frames[0].length === 320, "녹음 업로드는 파일째, 실시간은 20 ms 조각으로 보내요.");
  check(fin.text === "진료 비용" && frames.length >= Math.floor(voice16.length / 320) - 1, "16 kHz로 바꿔 보내도 같은 말로 받아써져야 해요.");
  ws.close();
  console.log("서버 종료:", await closeServer(server));
}

main();

