const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

function isSecureContext_(origin: string): boolean {
  // 브라우저는 https 또는 localhost 에서만 마이크 API(navigator.mediaDevices)를 열어 준다
  const u = new URL(origin);
  return u.protocol === "https:" || ["localhost", "127.0.0.1", "[::1]"].includes(u.hostname);
}

function getUserMedia(origin: string, permission: string, hasMic: boolean): string {
  // 브라우저의 getUserMedia 결과를 흉내 냄 (대체 경로: 진짜 브라우저 · 마이크 없이 규칙만)
  if (!isSecureContext_(origin)) return "TypeError"; // navigator.mediaDevices 자체가 undefined
  if (permission === "denied") return "NotAllowedError"; // 사용자가 '차단'을 눌렀거나 정책이 막음
  if (!hasMic) return "NotFoundError"; // 마이크 장치가 없음
  return "stream";
}

const HELP: Record<string, string> = {
  TypeError: "주소가 https인지 확인해요 (개발 중에는 localhost)",
  NotAllowedError: "주소창 자물쇠에서 마이크를 '허용'으로 바꿔요",
  NotFoundError: "마이크를 연결하고 다시 시도해요",
  stream: "녹음 시작!",
};

function micAllowed(policy: string, page: string, frame: string): boolean {
  // Permissions-Policy: microphone=(self) 이면 같은 출처의 페이지만 마이크를 쓸 수 있다 (다른 출처 iframe은 거절)
  const value = policy.split("microphone=")[1].replace(/[()]/g, "").trim();
  return value === "self" ? frame === page : value === "*" || value === "";
}

const PAGE = `<button id="start">녹음</button>
<script>$("start").onclick = async () => { const s = await navigator.mediaDevices.getUserMedia({audio: true}); };</script>`;

const server = createServer((req, res) => {
  if (req.url === "/rec") {
    res.writeHead(200, { "content-type": "text/html; charset=utf-8", "permissions-policy": "microphone=(self)" });
    return res.end(PAGE);
  }
  sendJson(res, 404, { detail: "없는 주소" });
});

async function main(): Promise<void> {
  const cases: [string, string, boolean][] = [
    ["https://hanbit.example", "granted", true],
    ["http://localhost:8000", "granted", true],
    ["http://192.168.0.5:8000", "granted", true],
    ["https://hanbit.example", "denied", true],
    ["https://hanbit.example", "granted", false],
  ];
  const got: string[] = [];
  for (const [origin, perm, mic] of cases) {
    const r = getUserMedia(origin, perm, mic);
    got.push(r);
    console.log(`${origin.padEnd(26)} 권한 ${perm.padEnd(8)} 마이크 ${String(mic).padEnd(5)} → ${r.padEnd(16)} ${HELP[r]}`);
  }
  check(got.join() === "stream,stream,TypeError,NotAllowedError,NotFoundError", "https · 권한 · 장치 순서로 막혀요.");

  const host = await listen(server);
  const r = await fetch(`http://${host}/rec`);
  const html = await r.text();
  const policy = r.headers.get("permissions-policy") ?? "";
  const base = `http://${host}`;
  console.log("서버가 보낸 정책:", policy, "· 같은 출처 허용:", micAllowed(policy, base, base), "· 다른 출처 허용:", micAllowed(policy, base, "https://ads.example"));
  check(r.status === 200 && html.includes("getUserMedia") && html.includes("onclick"), "마이크는 버튼 누름(onclick) 안에서 요청해야 해요.");
  check(micAllowed(policy, base, base) && !micAllowed(policy, base, "https://ads.example"), "microphone=(self)는 다른 출처에 마이크를 주지 않아요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

rec.typescript:
// D32 · Part 1 · MediaRecorder 녹음 → 업로드 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_rec.ts   (서버는 임시 포트로 띄우고 브라우저 대신 같은 파일이 녹음 조각을 올림 · 마이크 불필요)
//   MediaRecorder처럼 250 ms 조각으로 녹음 → 조각을 이어 파일(Blob) → FormData(multipart)로 올리기 → 서버가 받아쓰기
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

const UPLOADS: { type: string; bytes: number }[] = []; // 서버가 브라우저에게서 받은 것 기록

const server = createServer(async (req, res) => {
  if (req.method === "POST" && req.url === "/upload") {
    const f = await readFile(req);
    if (!f) return sendJson(res, 422, { detail: "file 칸이 없어요" });
    UPLOADS.push({ type: f.type, bytes: f.data.length });
    try {
      const y = decodeWav(f.data);
      return sendJson(res, 200, { text: hear(y), audio_sec: Math.round((y.length / SR) * 100) / 100, bytes: f.data.length });
    } catch {
      // 진짜 브라우저는 audio/webm(Opus)를 보내서 서버에 ffmpeg가 필요하지만, 이 코드의 서버는 WAV만 푼다
      return sendJson(res, 400, { detail: `${f.type}는 풀 수 없어요 (ffmpeg 필요)` });
    }
  }
  sendJson(res, 404, { detail: "없는 주소" });
});

function recordChunks(y: Float32Array, sliceMs: number = 250): Buffer[] {
  // MediaRecorder.start(250): 250 ms마다 조각(ondataavailable) 하나. 대체 경로: 압축 없이 PCM16 조각
  const n = Math.floor((SR * sliceMs) / 1000);
  const out: Buffer[] = [];
  for (let i = 0; i < y.length; i += n) {
    const part = y.subarray(i, Math.min(y.length, i + n));
    const b = Buffer.alloc(part.length * 2);
    part.forEach((v, k) => b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, v)) * 32767), k * 2));
    out.push(b);
  }
  return out;
}

function toBlob(chunks: Buffer[]): Buffer {
  // 조각을 이어 붙여 하나의 파일(Blob)로: new Blob(chunks, {type})
  const pcm = Buffer.concat(chunks);
  const y = new Float32Array(pcm.length >> 1);
  for (let i = 0; i < y.length; i++) y[i] = pcm.readInt16LE(i * 2) / 32768;
  return wavBytes(y);
}

async function main(): Promise<void> {
  const host = await listen(server);
  const voice = say(["진료", "예약", "비용"]); // 대체 경로: 가짜 마이크 소리 (톤 세 개)
  const chunks = recordChunks(voice);
  const blob = toBlob(chunks);
  console.log(`녹음 ${(voice.length / SR).toFixed(2)}초 → 조각 ${chunks.length}개 → Blob ${blob.length.toLocaleString()}바이트`);
  check(chunks.length === Math.ceil(voice.length / (SR / 4)), "조각 수 = 길이 / 0.25초(올림)예요.");

  const r = await fetch(`http://${host}/upload`, { method: "POST", body: uploadForm(blob) }); // FormData: 파일 칸 이름 'file'
  const body = (await r.json()) as { text: string; audio_sec: number };
  console.log("업로드 →", r.status, body);
  const webm = await fetch(`http://${host}/upload`, { method: "POST", body: uploadForm(Buffer.from("\x1aE\xdf\xa3junk"), "audio/webm") });
  const webmBody = (await webm.json()) as { detail: string };
  console.log("WebM 업로드 →", webm.status, webmBody.detail);
  check(r.status === 200 && body.text === "진료 예약 비용" && Math.abs(body.audio_sec - voice.length / SR) < 0.01, "올린 파일을 서버가 풀어 받아쓰기해야 해요.");
  check(UPLOADS[0].type === "audio/wav" && webm.status === 400, "content-type이 서버에 전달돼요. 못 푸는 형식은 400이에요.");

  const opusBytes = Math.floor(((voice.length / SR) * 24000) / 8); // 가정: Opus 24 kbps
  console.log(`같은 길이: WAV ${blob.length.toLocaleString()}바이트 vs Opus(24 kbps 가정) 약 ${opusBytes.toLocaleString()}바이트 → 약 1/${Math.floor(blob.length / opusBytes)}`);
  check(Math.floor(blob.length / opusBytes) >= 8, "압축 형식(Opus)은 같은 소리를 WAV의 10분의 1쯤으로 줄여요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

graph.typescript:
// D32 · Part 2 · Web Audio 그래프 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_graph.ts   (브라우저 없이 '노드를 이어 붙이는' 그래프를 직접 구현 · 마이크 불필요)
//   Web Audio의 '노드를 선으로 이어 붙이는' 방식: source → gain → analyser → destination. 128샘플 블록마다 아래서 위로 끌어옴
const SR = 16000;
const BLOCK = 128; // Web Audio가 한 번에 처리하는 크기(render quantum)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class AudioNode_ {
  inputs: AudioNode_[] = [];
  connect<T extends AudioNode_>(other: T): T {
    // a.connect(b): a의 소리가 b로 흐름 (b를 돌려줘 줄줄이 이을 수 있음)
    other.inputs.push(this);
    return other;
  }
  disconnect(other: AudioNode_): void {
    other.inputs.splice(other.inputs.indexOf(this), 1);
  }
  pull(k: number): Float32Array {
    // k번째 블록: 들어오는 소리를 모두 더한 뒤 이 노드가 처리
    const x = new Float32Array(BLOCK);
    for (const inp of this.inputs) inp.pull(k).forEach((v, i) => (x[i] += v));
    return this.process(x, k);
  }
  process(x: Float32Array, _k: number): Float32Array {
    return x;
  }
}

class Source extends AudioNode_ {
  // 소리를 내보내는 노드 (마이크 · 파일)
  y: Float32Array;
  constructor(y: Float32Array) {
    super();
    this.y = y;
  }
  process(_x: Float32Array, k: number): Float32Array {
    const b = new Float32Array(BLOCK);
    b.set(this.y.subarray(k * BLOCK, (k + 1) * BLOCK));
    return b;
  }
}

class Gain extends AudioNode_ {
  // 소리 크기 조절 노드
  gain: number;
  constructor(gain: number) {
    super();
    this.gain = gain;
  }
  process(x: Float32Array): Float32Array {
    return x.map((v) => v * this.gain);
  }
}

class Analyser extends AudioNode_ {
  // 소리를 바꾸지 않고 크기만 재는 노드 (화면의 크기 막대)
  rms: number = 0;
  process(x: Float32Array): Float32Array {
    this.rms = Math.sqrt(x.reduce((a, v) => a + v * v, 0) / x.length);
    return x;
  }
}

class Destination extends AudioNode_ {
  // 스피커: 도착한 블록을 모음
  blocks: Float32Array[] = [];
  process(x: Float32Array): Float32Array {
    this.blocks.push(x);
    return x;
  }
}

function render(dest: Destination, nBlocks: number): Float32Array {
  dest.blocks = [];
  for (let k = 0; k < nBlocks; k++) dest.pull(k);
  const out = new Float32Array(nBlocks * BLOCK);
  dest.blocks.forEach((b, k) => out.set(b, k * BLOCK));
  return out;
}

function close(a: Float32Array, b: Float32Array, tol: number): boolean {
  return a.length <= b.length && a.every((v, i) => Math.abs(v - b[i]) <= tol);
}

const y = Float32Array.from({ length: SR }, (_, i) => 0.4 * Math.sin((2 * Math.PI * 440 * i) / SR)); // 대체 경로: 마이크 대신 합성 사인파 1초
const nBlocks = Math.floor(y.length / BLOCK);

const src = new Source(y);
const gain = new Gain(0.5);
const ana = new Analyser();
const dest = new Destination();
src.connect(gain).connect(ana).connect(dest); // 줄줄이 연결
const out = render(dest, nBlocks);
const half = y.map((v) => 0.5 * v);
console.log(`블록 ${nBlocks}개 · 출력 최대 ${Math.max(...out.map(Math.abs)).toFixed(3)} (입력 0.4 × 이득 0.5) · 마지막 블록 크기(RMS) ${ana.rms.toFixed(3)}`);
check(close(out, half, 1e-6) && Math.abs(ana.rms - 0.2 / Math.SQRT2) < 0.01, "이득 0.5를 거친 소리는 절반 크기, RMS는 진폭 / 루트2예요.");

// 한 소리를 두 갈래로: 같은 source를 gain 두 개에 이으면 갈래마다 처리되고, 목적지에서 더해진다 (소리 섞기)
const src2 = new Source(y);
const dest2 = new Destination();
src2.connect(new Gain(0.3)).connect(dest2);
src2.connect(new Gain(0.2)).connect(dest2);
check(close(render(dest2, nBlocks), half, 1e-6), "두 갈래 이득 0.3 + 0.2 = 0.5가 더해져야 해요.");

// 연결 끊기: 음소거 버튼은 gain을 0으로 하거나 선을 끊는 일
gain.disconnect(ana);
const muted = render(dest, nBlocks);
console.log(`gain → analyser 선을 끊은 뒤 출력 최대 ${Math.max(...muted.map(Math.abs)).toFixed(3)}`);
check(muted.every((v) => v === 0), "선을 끊으면 목적지에는 조용함만 도착해요.");

resample.typescript:
// D32 · Part 2 · AudioWorklet 16kHz 변환 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_resample.ts   (브라우저 없이 워클릿 규칙(128샘플 블록)을 그대로 옮김 · 마이크 불필요)
//   마이크 48 kHz(또는 44.1 kHz) → 128샘플 블록 → 선형 보간 → 16 kHz PCM16 320샘플 조각. 블록 경계 · 소수 비율 · 접힘(aliasing)까지 확인
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class Resampler {
  // AudioWorklet의 PCMWorklet을 그대로 옮긴 것: 마이크 소리(48 kHz 등)를 128샘플 블록씩 받아 16 kHz · 16비트 · 320샘플(20 ms) 조각으로 낸다
  ratio: number; // 48000 → 3, 44100 → 2.75625
  frame: number;
  pos: number = 0; // 다음에 고를 위치
  prev: number = 0; // 앞 블록의 마지막 값
  buf: number[] = [];
  constructor(inRate: number, outRate: number = 16000, frame: number = 320) {
    this.ratio = inRate / outRate;
    this.frame = frame;
  }
  process(x: Float32Array): Int16Array[] {
    const frames: Int16Array[] = [];
    while (this.pos < x.length - 1) {
      const i = Math.floor(this.pos);
      const f = this.pos - i;
      const a = i < 0 ? this.prev : x[i];
      const b = i < 0 ? x[0] : x[i + 1];
      const v = a + (b - a) * f; // 선형 보간
      this.buf.push(Math.trunc(Math.max(-1, Math.min(1, v)) * 32767)); // -1 ~ 1 실수 → 16비트 정수
      if (this.buf.length === this.frame) {
        // 20 ms 모임 → 화면 스레드로
        frames.push(Int16Array.from(this.buf));
        this.buf = [];
      }
      this.pos += this.ratio;
    }
    this.pos -= x.length;
    this.prev = x[x.length - 1];
    return frames;
  }
}

function runWorklet(y: Float32Array, inRate: number, block: number = 128): Float32Array {
  // 소리 전체를 128샘플 블록으로 잘라 워클릿에 흘려 넣고, 나온 조각을 이어 붙인다
  const w = new Resampler(inRate);
  const out: number[] = [];
  for (let i = 0; i + block <= y.length; i += block) for (const f of w.process(y.subarray(i, i + block))) for (const v of f) out.push(v / 32767);
  return Float32Array.from(out);
}

function tone(freq: number, rate: number, sec: number = 1, amp: number = 0.5): Float32Array {
  const y = new Float32Array(Math.floor(rate * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin((2 * Math.PI * freq * i) / rate);
  return y;
}

function maxDiff(a: Float32Array, b: ArrayLike<number>, from: number = 2): number {
  let m = 0;
  for (let i = from; i < Math.min(a.length, b.length); i++) m = Math.max(m, Math.abs(a[i] - b[i]));
  return m;
}

// 1) 48 kHz → 16 kHz: 440 Hz 사인파가 그대로 보존되는가 (대체 경로: 진짜 마이크 대신 합성 사인파)
const x48 = tone(440, 48000);
const out = runWorklet(x48, 48000);
const err = maxDiff(out, tone(440, SR));
console.log(`48 kHz ${x48.length.toLocaleString()}샘플 → 16 kHz ${out.length.toLocaleString()}샘플 (비율 ${(x48.length / out.length).toFixed(3)}) · 이상적인 사인과 최대 차이 ${err.toFixed(4)}`);
check(Math.abs(out.length - 16000) <= 320 && err < 0.01, "48000 / 16000 = 3 이라 3개마다 하나씩 고르면 돼요.");

// 2) 44.1 kHz: 비율이 2.75625처럼 소수 → 블록 경계에서 위치와 앞 값을 이어받아야 끊김이 없다
const x44 = tone(440, 44100);
const out44 = runWorklet(x44, 44100);
const ideal44 = Float32Array.from({ length: out44.length }, (_, i) => 0.5 * Math.sin((2 * Math.PI * 440 * i) / SR));
const err44 = maxDiff(out44, ideal44);
console.log(`44.1 kHz → 비율 ${44100 / 16000} · 출력 ${out44.length.toLocaleString()}샘플 · 이상적인 사인과 최대 차이 ${err44.toFixed(4)}`);
check(Math.abs(out44.length - 16000) <= 320 && err44 < 0.02, "소수 비율에서도 블록 경계에서 끊기지 않아야 해요.");

// 3) 블록 크기와 상관없이 같은 결과: 128샘플씩 vs 한꺼번에 넣기
const small = runWorklet(x44.subarray(0, 128 * 300), 44100, 128);
const bigFrames = new Resampler(44100).process(x44.subarray(0, 128 * 300));
const big = Float32Array.from(bigFrames.flatMap((f) => Array.from(f, (v) => v / 32767)));
const n = Math.min(small.length, big.length);
const d3 = maxDiff(small.subarray(0, n), big.subarray(0, n), 0);
console.log(`128샘플 블록 vs 한꺼번에: 앞 ${n.toLocaleString()}샘플의 최대 차이 ${d3.toFixed(5)}`);
check(n > 1000 && d3 < 1e-3, "앞 블록의 마지막 값(prev)과 위치(pos)를 넘겨받아야 같은 결과예요.");

// 4) 주의: 낮은 표본율로 줄일 때 저역통과 없이 고르기만 하면 8 kHz 넘는 소리가 접혀 들어온다
const hi = runWorklet(tone(10000, 48000), 48000);
const N = 4096;
let peakFreq = 0;
let peakMag = -1;
for (let k = 1; k < N / 2; k++) {
  // 꼭 필요한 주파수만 훑는 DFT(1 kHz ~ 7.9 kHz)
  const f = (k * SR) / N;
  if (f < 1000 || f > 7900) continue;
  let re = 0;
  let im = 0;
  for (let i = 0; i < N; i++) {
    const w = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (N - 1)); // 한(Hann) 창
    re += hi[i] * w * Math.cos((2 * Math.PI * k * i) / N);
    im -= hi[i] * w * Math.sin((2 * Math.PI * k * i) / N);
  }
  if (re * re + im * im > peakMag) {
    peakMag = re * re + im * im;
    peakFreq = f;
  }
}
console.log(`10 kHz 소리를 16 kHz로 줄였더니 ${peakFreq.toFixed(0)} Hz에서 가장 크게 나타남 (16000 - 10000 = 6000 Hz로 접힘)`);
check(Math.abs(peakFreq - 6000) < 100, "나이퀴스트(8 kHz)를 넘는 소리는 16000 - 주파수 자리로 접혀요.");

queue.typescript:
// D32 · Part 3 · 답 소리 재생 큐 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_queue.ts   (브라우저 없이 AudioContext 시계를 흉내 낸 예약 규칙 · 마이크 불필요)
//   답 소리 조각이 들쭉날쭉 도착해도 끊기지 않게: 다음 재생 시각(nextTime)을 기억해 '앞 조각이 끝나는 순간'에 이어 붙이기
const SAFETY = 0.02; // 너무 늦게 예약하지 않도록 두는 여유(초)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class PlayQueue {
  // AudioContext 시계(currentTime)에 소리 조각의 시작 시각을 예약하는 규칙 (대체 경로: 진짜 AudioContext 대신 시각 계산)
  nextTime: number = 0; // 앞 조각이 끝나는 시각
  scheduled: [number, number][] = []; // (시작, 길이)
  schedule(now: number, dur: number): number {
    const start = Math.max(now + SAFETY, this.nextTime); // 이미 지난 시각이면 지금 바로, 아니면 앞 조각 뒤에
    this.nextTime = start + dur;
    this.scheduled.push([start, dur]);
    return start;
  }
  flush(now: number): number {
    // 끼어들기: 아직 시작 안 한 조각을 모두 취소
    const left = this.scheduled.filter((s) => s[0] > now).length;
    this.scheduled = this.scheduled.filter((s) => s[0] <= now);
    this.nextTime = now;
    return left;
  }
}

const r2 = (v: number): number => Math.round(v * 100) / 100;

// 서버가 문장 소리를 이 시각(초)에 보내 줬다고 하자. 조각 하나는 0.5초 분량.
const arrivals = [0.0, 0.05, 0.1, 0.12, 3.5]; // 앞 4개는 한꺼번에 몰려 오고, 마지막은 한참 늦게 옴
const q = new PlayQueue();
const starts = arrivals.map((t) => q.schedule(t, 0.5));
const ends = starts.map((s) => s + 0.5);
arrivals.forEach((a, k) => console.log(`조각 ${k + 1}: 도착 ${a.toFixed(2)}초 → 재생 시작 ${starts[k].toFixed(2)}초 (기다린 시간 ${(starts[k] - a).toFixed(2)}초)`));

const overlap = starts.slice(1).some((s, i) => s < ends[i] - 1e-9);
const gaps = starts.slice(1).map((s, i) => r2(s - ends[i]));
console.log("조각 사이 빈틈(초):", gaps);
check(!overlap, "앞 조각이 끝나기 전에 다음 조각이 시작하면 소리가 겹쳐요.");
check(gaps.slice(0, 3).every((g) => g === 0), "몰려 온 조각은 빈틈 없이 이어 붙어야 해요.");
check(gaps[3] > 1.0, "너무 늦게 온 조각 앞에는 빈틈(끊김)이 생겨요: 이게 버퍼가 비는 순간(underrun)이에요.");

// 도착이 재생보다 빠르면: 줄을 서며 끊김은 없다
const q2 = new PlayQueue();
const arrivals2 = [0.0, 0.3, 0.6, 0.9]; // 0.3초 간격으로 오는데 조각은 0.5초 → 빨리 쌓임
const starts2 = arrivals2.map((t) => q2.schedule(t, 0.5));
const gaps2 = [0, 1, 2].map((i) => r2(starts2[i + 1] - (starts2[i] + 0.5)));
console.log("빨리 쌓이는 경우 빈틈:", gaps2, "· 마지막 조각 기다린 시간", r2(starts2[3] - arrivals2[3]), "초");
check(gaps2.every((g) => g === 0) && starts2[3] - arrivals2[3] > 0.5, "도착이 재생보다 빠르면 줄을 서며 끊김은 없어요.");

// 끼어들기: flush하면 아직 시작 안 한 조각이 취소되고 새 답은 지금 바로 시작
const now = 0.6;
const cancelled = q.flush(now);
const fresh = q.schedule(now, 0.4);
console.log(`${now}초에 끼어들기 → 취소된 조각 ${cancelled}개 · 새 답 재생 시작 ${fresh.toFixed(2)}초`);
check(cancelled === 3 && Math.abs(fresh - (now + SAFETY)) < 1e-9, "흘러가던 조각 중 아직 시작 안 한 것만 취소되고 새 소리는 곧바로 시작해요.");

barge.typescript:
// D32 · Part 3 · 끼어들기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_barge.ts   (서버는 임시 포트로 띄우고 같은 파일의 클라이언트가 말을 끊음 · 마이크 불필요)
//   답을 문장 단위로 흘려보내는 도중 사용자가 말하면: 클라이언트가 재생 큐를 비우고 'barge'를 보내 서버가 남은 문장을 멈춤
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";

const SR = 16000;
const WORDS: Record<string, number> = { 진료: 500, 주차: 700, 비용: 900, 예약: 1100 };
// 대체 경로: 진짜 TTS · Whisper 대신 '단어 하나 = 0.25초 톤 하나'로 소리를 만들고 주파수로 알아듣는다

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function say(words: string[], gap: number = 0.15): Float32Array {
  // 단어 목록 → 소리(TTS 흉내): 단어마다 고유 주파수의 톤 + 짧은 쉼
  const n = Math.floor(0.25 * SR);
  const g = Math.floor(gap * SR);
  const y = new Float32Array(words.length * (n + g));
  words.forEach((w, k) => {
    for (let i = 0; i < n; i++) y[k * (n + g) + i] = 0.4 * Math.sin((2 * Math.PI * WORDS[w] * i) / SR);
  });
  return y;
}

function speak(text: string): Float32Array {
  // 글자 → 소리: 글자 안에 있는 키워드만 소리로 낸다
  const ws = Object.keys(WORDS).filter((w) => text.includes(w)).sort((a, b) => text.indexOf(a) - text.indexOf(b));
  return say(ws.length ? ws : ["예약"]);
}

function nearestWord(seg: Float32Array): string {
  let best = "";
  let bestMag = -1;
  for (const [w, f] of Object.entries(WORDS)) {
    let re = 0;
    let im = 0;
    for (let i = 0; i < seg.length; i++) {
      re += seg[i] * Math.cos((2 * Math.PI * f * i) / SR);
      im += seg[i] * Math.sin((2 * Math.PI * f * i) / SR);
    }
    if (re * re + im * im > bestMag) {
      bestMag = re * re + im * im;
      best = w;
    }
  }
  return best;
}

function hear(y: Float32Array): string {
  // 소리 → 글자(STT 흉내): 20 ms 조각이 큰 구간마다 가장 닮은 주파수의 단어를 고른다
  const n = SR / 50;
  const loud: boolean[] = [];
  for (let i = 0; i + n <= y.length; i += n) {
    let s = 0;
    for (let j = 0; j < n; j++) s += y[i + j] * y[i + j];
    loud.push(Math.sqrt(s / n) > 0.05);
  }
  loud.push(false);
  const words: string[] = [];
  let start = -1;
  loud.forEach((v, k) => {
    if (v && start < 0) start = k;
    else if (!v && start >= 0) {
      words.push(nearestWord(y.subarray(start * n, k * n)));
      start = -1;
    }
  });
  return words.join(" ");
}

function wavBytes(y: Float32Array): Buffer {
  // 16비트 모노 WAV 파일 바이트 (머리 44바이트 + 샘플)
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0);
  b.writeUInt32LE(36 + y.length * 2, 4);
  b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16);
  b.writeUInt16LE(1, 20);
  b.writeUInt16LE(1, 22);
  b.writeUInt32LE(SR, 24);
  b.writeUInt32LE(SR * 2, 28);
  b.writeUInt16LE(2, 32);
  b.writeUInt16LE(16, 34);
  b.write("data", 36);
  b.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, y[i])) * 32767), 44 + i * 2);
  return b;
}

function decodeWav(buf: Buffer): Float32Array {
  if (buf.length < 44 || buf.toString("latin1", 0, 4) !== "RIFF" || buf.toString("latin1", 8, 12) !== "WAVE") throw new Error("소리로 풀 수 없는 파일");
  const n = (buf.length - 44) >> 1;
  const y = new Float32Array(n);
  for (let i = 0; i < n; i++) y[i] = buf.readInt16LE(44 + i * 2) / 32768;
  return y;
}

function listen(server: Server): Promise<string> {
  // 임시 포트(0번)를 운영체제에서 받아 서버를 띄운다 → "127.0.0.1:포트"
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(`127.0.0.1:${(server.address() as AddressInfo).port}`)));
}

function closeServer(server: Server): Promise<boolean> {
  server.closeAllConnections();
  return new Promise((resolve) => server.close(() => resolve(!server.listening)));
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(body));
}

async function readBody(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks);
}

async function readFile(req: IncomingMessage): Promise<{ type: string; data: Buffer } | null> {
  // multipart/form-data에서 'file' 칸 꺼내기 (Node 내장 Response.formData 사용). 없거나 multipart가 아니면 null
  try {
    const form = await new Response(await readBody(req), { headers: { "content-type": req.headers["content-type"] ?? "" } }).formData();
    const f = form.get("file");
    return f instanceof File ? { type: f.type, data: Buffer.from(await f.arrayBuffer()) } : null;
  } catch {
    return null;
  }
}

function uploadForm(wav: Uint8Array, type: string = "audio/wav", field: string = "file"): FormData {
  const form = new FormData();
  form.append(field, new Blob([wav as BlobPart], { type }), "v.wav");
  return form;
}

const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

type WsPeer = { onmessage: ((data: Buffer, isBinary: boolean) => void) | null; send: (data: string | Uint8Array) => void; close: () => void };

function serveWs(server: Server, path: string, handler: (ws: WsPeer) => void): void {
  // Node에는 WebSocket '서버'가 내장돼 있지 않아 HTTP Upgrade(101)와 프레임 읽기 · 쓰기를 직접 구현 (텍스트 · 바이너리만)
  server.on("upgrade", (req, socket) => {
    if (req.url !== path) {
      socket.destroy();
      return;
    }
    const accept = createHash("sha1").update(String(req.headers["sec-websocket-key"]) + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").digest("base64");
    socket.write(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`);
    const ws: WsPeer = {
      onmessage: null,
      send(data) {
        const op = typeof data === "string" ? 1 : 2;
        const p = Buffer.from(data);
        const head = p.length < 126 ? Buffer.from([0x80 | op, p.length]) : Buffer.from([0x80 | op, 126, p.length >> 8, p.length & 255]);
        socket.write(Buffer.concat([head, p]));
      },
      close() {
        socket.end(Buffer.from([0x88, 0]));
      },
    };
    let buf = Buffer.alloc(0);
    socket.on("data", (chunk: Buffer) => {
      buf = Buffer.concat([buf, chunk]);
      for (;;) {
        if (buf.length < 2) return;
        const opcode = buf[0] & 15;
        let len = buf[1] & 127;
        let off = 2;
        if (len === 126) {
          if (buf.length < 4) return;
          len = buf.readUInt16BE(2);
          off = 4;
        } else if (len === 127) {
          if (buf.length < 10) return;
          len = Number(buf.readBigUInt64BE(2));
          off = 10;
        }
        if (buf.length < off + 4 + len) return;
        const mask = buf.subarray(off, off + 4);
        const data = Buffer.from(buf.subarray(off + 4, off + 4 + len));
        for (let i = 0; i < len; i++) data[i] ^= mask[i % 4];
        buf = buf.subarray(off + 4 + len);
        if (opcode === 8) {
          socket.end();
          return;
        }
        if (opcode === 1 || opcode === 2) ws.onmessage?.(data, opcode === 2);
      }
    });
    socket.on("error", () => {});
    handler(ws);
  });
}

function wsConnect(host: string, path: string): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://${host}${path}`);
    ws.binaryType = "arraybuffer";
    ws.onopen = () => resolve(ws);
    ws.onerror = () => reject(new Error("WebSocket 연결 실패"));
  });
}

const ANSWER = ["평일은 아홉 시 반부터 진료합니다.", "토요일은 한 시까지예요.", "주차는 두 시간 무료입니다.", "예약은 앱에서 하세요."];
const SERVER = { sent: 0 };

const server = createServer((_req, res) => sendJson(res, 404, { detail: "WebSocket만 받아요" }));
serveWs(server, "/ws/voice", (ws) => {
  let cancelled = false;
  ws.onmessage = (data) => {
    if (data.toString() === "barge") {
      // 사용자가 말하기 시작함 → 남은 문장 취소
      cancelled = true;
      ws.send(JSON.stringify({ type: "stopped", sent: SERVER.sent }));
    }
  };
  (async () => {
    // 문장마다 소리를 만들어 보내는 일 (한 문장 = 바이너리 하나)
    for (let i = 0; i < ANSWER.length && !cancelled; i++) {
      await sleep(150); // 문장 하나를 합성하는 시간 흉내
      if (cancelled) return;
      ws.send(wavBytes(speak("진료")));
      SERVER.sent++;
    }
    if (!cancelled) ws.send(JSON.stringify({ type: "audio_end" }));
  })();
});

async function call(host: string, bargeAfter: number | null): Promise<[number, number]> {
  // 답을 받으면서 재생 큐에 쌓는다. bargeAfter번째 조각을 받으면 큐를 비우고 barge를 보낸다 → [재생 큐 길이, 서버가 보낸 수]
  SERVER.sent = 0;
  const queue: ArrayBuffer[] = [];
  const ws = await wsConnect(host, "/ws/voice");
  await new Promise<void>((resolve) => {
    ws.onmessage = (e) => {
      if (e.data instanceof ArrayBuffer) {
        queue.push(e.data);
        if (bargeAfter && queue.length === bargeAfter) {
          queue.length = 0; // 재생 큐 비우기(스피커 즉시 멈춤)
          ws.send("barge");
        }
      } else if (["audio_end", "stopped"].includes(JSON.parse(String(e.data)).type)) resolve();
    };
  });
  ws.close();
  return [queue.length, SERVER.sent];
}

async function main(): Promise<void> {
  const host = await listen(server);
  const [qFull, sentFull] = await call(host, null);
  const [qCut, sentCut] = await call(host, 1);
  console.log(`끼어들기 없음: 서버가 보낸 문장 소리 ${sentFull}개 · 재생 큐 ${qFull}개`);
  console.log(`첫 문장 직후 끼어들기: 서버가 보낸 소리 ${sentCut}개 · 재생 큐 ${qCut}개 (비워짐)`);
  check(sentFull === ANSWER.length && qFull === ANSWER.length, "끼어들기가 없으면 답 문장이 모두 와요.");
  check(sentCut < ANSWER.length && qCut === 0, "끼어들면 서버가 남은 문장을 멈추고 클라이언트 큐는 비어야 해요.");
  console.log("서버 종료:", await closeServer(server));
}

main();

compare.typescript:
// D32 · Part 4 · WebSocket vs WebRTC — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_compare.ts   (네트워크 없이 크기 · 지연을 계산으로 비교)
//   WebSocket(TCP, 원본 PCM) vs WebRTC(UDP, Opus): 20 ms 조각 하나의 크기 · 초당 전송량 · 손실 났을 때 지연을 계산으로 비교
const SR = 16000;
const FRAME_SEC = 0.02;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 대체 경로: 진짜 네트워크 대신 헤더 크기와 Opus 비트레이트(24 kbps, 음성용 흔한 설정)를 가정한 계산
const PCM_BYTES = Math.floor(SR * FRAME_SEC) * 2; // 320샘플 × 2바이트 = 640
const WS_HEADER = 6 + 20 + 20; // 웹소켓 프레임(마스크 포함) + TCP 20 + IP 20
const OPUS_BYTES = Math.floor(((24000 / 8) * FRAME_SEC)); // 24 kbps → 20 ms에 60바이트
const RTP_HEADER = 12 + 8 + 20; // RTP 12 + UDP 8 + IP 20
const wsTotal = PCM_BYTES + WS_HEADER;
const rtcTotal = OPUS_BYTES + RTP_HEADER;
const wsKbps = (wsTotal * 8) / FRAME_SEC / 1000;
const rtcKbps = (rtcTotal * 8) / FRAME_SEC / 1000;
console.log(`WebSocket PCM16: 조각 ${wsTotal}바이트 → ${wsKbps.toFixed(0)} kbps`);
console.log(`WebRTC Opus:     조각 ${rtcTotal}바이트 → ${rtcKbps.toFixed(0)} kbps (약 ${(wsKbps / rtcKbps).toFixed(1)}배 적음)`);
check(PCM_BYTES === 640 && wsKbps > 4 * rtcKbps, "원본 PCM16은 압축한 Opus보다 몇 배 많이 보내요.");

// 손실이 나면: TCP는 잃어버린 조각을 다시 받을 때까지 뒤 조각이 줄을 서고(head-of-line blocking), UDP는 건너뛴다
const rand = mulberry32(7);
const N = 1000;
const RTT = 0.06; // 왕복 60 ms
const LOSS = 0.03; // 손실 3%
const lost = Array.from({ length: N }, () => rand() < LOSS);
const sendT = Array.from({ length: N }, (_, i) => i * FRAME_SEC);
let latest = 0;
const arriveTcp = sendT.map((t, i) => {
  // 손실 조각은 재전송(+RTT)으로 늦게 도착, 뒤 조각은 그 뒤에야 전달됨(순서대로만 전달)
  latest = Math.max(latest, t + RTT / 2 + (lost[i] ? RTT : 0));
  return latest;
});
const delayTcp = arriveTcp.map((a, i) => (a - sendT[i]) * 1000);
const delayUdp = sendT.map(() => (RTT / 2) * 1000); // 손실은 그냥 빠짐(Opus는 빈 조각을 메워 숨김)
const nLost = lost.filter(Boolean).length;
const mean = (a: number[]): number => a.reduce((x, y) => x + y, 0) / a.length;
console.log(`손실 ${nLost}개(${((nLost / N) * 100).toFixed(1)}%) · 지연 평균 WebSocket ${mean(delayTcp).toFixed(0)} ms (최대 ${Math.max(...delayTcp).toFixed(0)}) · WebRTC ${mean(delayUdp).toFixed(0)} ms (최대 ${Math.max(...delayUdp).toFixed(0)}, 소리 ${nLost}조각 빠짐)`);
check(Math.max(...delayTcp) >= Math.max(...delayUdp) + RTT * 1000 - 1 && mean(delayTcp) > mean(delayUdp), "TCP는 손실 때 뒤 조각까지 기다려 지연이 늘어요.");
check(nLost > 0 && delayUdp.every((d) => d === (RTT / 2) * 1000), "UDP는 지연은 일정하지만 손실된 조각은 사라져요.");

// 어느 쪽을 고를까: 서버 인프라가 간단한 쪽 vs 끊김 없는 통화 품질
const choice: Record<string, string> = { "프로토타입 · 사내 도구": "WebSocket", "전화처럼 안정적인 통화(손실 많은 모바일망)": "WebRTC" };
console.log("권장:", choice);
check(choice["프로토타입 · 사내 도구"] === "WebSocket" && choice["전화처럼 안정적인 통화(손실 많은 모바일망)"] === "WebRTC", "단순함은 WebSocket, 통화 품질은 WebRTC예요.");

recap.typescript:
// D32 · Part 5 · 정리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d32_recap.ts   (서버 없이 핵심 숫자와 규칙을 한 번씩 확인)
//   브라우저 음성 클라이언트의 핵심 숫자와 규칙(권한 · 녹음 조각 · 16 kHz 변환 · PCM16 · 재생 큐 · 끼어들기)을 한 번씩 확인
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class Resampler {
  // AudioWorklet의 PCMWorklet을 그대로 옮긴 것: 마이크 소리(48 kHz 등)를 128샘플 블록씩 받아 16 kHz · 16비트 · 320샘플(20 ms) 조각으로 낸다
  ratio: number; // 48000 → 3, 44100 → 2.75625
  frame: number;
  pos: number = 0; // 다음에 고를 위치
  prev: number = 0; // 앞 블록의 마지막 값
  buf: number[] = [];
  constructor(inRate: number, outRate: number = 16000, frame: number = 320) {
    this.ratio = inRate / outRate;
    this.frame = frame;
  }
  process(x: Float32Array): Int16Array[] {
    const frames: Int16Array[] = [];
    while (this.pos < x.length - 1) {
      const i = Math.floor(this.pos);
      const f = this.pos - i;
      const a = i < 0 ? this.prev : x[i];
      const b = i < 0 ? x[0] : x[i + 1];
      const v = a + (b - a) * f; // 선형 보간
      this.buf.push(Math.trunc(Math.max(-1, Math.min(1, v)) * 32767)); // -1 ~ 1 실수 → 16비트 정수
      if (this.buf.length === this.frame) {
        // 20 ms 모임 → 화면 스레드로
        frames.push(Int16Array.from(this.buf));
        this.buf = [];
      }
      this.pos += this.ratio;
    }
    this.pos -= x.length;
    this.prev = x[x.length - 1];
    return frames;
  }
}

function runWorklet(y: Float32Array, inRate: number, block: number = 128): Float32Array {
  // 소리 전체를 128샘플 블록으로 잘라 워클릿에 흘려 넣고, 나온 조각을 이어 붙인다
  const w = new Resampler(inRate);
  const out: number[] = [];
  for (let i = 0; i + block <= y.length; i += block) for (const f of w.process(y.subarray(i, i + block))) for (const v of f) out.push(v / 32767);
  return Float32Array.from(out);
}

// 1) 보안 환경: getUserMedia는 https 또는 localhost에서만
function secure(origin: string): boolean {
  const u = new URL(origin);
  return u.protocol === "https:" || ["localhost", "127.0.0.1", "[::1]"].includes(u.hostname);
}
check(secure("https://hanbit.example") && secure("http://localhost:8000") && !secure("http://192.168.0.5:8000"), "https · localhost만 마이크를 쓸 수 있어요.");

// 2) MediaRecorder: timeslice 250 ms → 2초 녹음은 조각 8개
check(Math.ceil(2.0 / 0.25) === 8, "2초 / 0.25초 = 8조각이에요.");

// 3) 48 kHz 마이크 → 16 kHz: 비율 3, 20 ms 조각 = 320샘플 = 640바이트
const x = Float32Array.from({ length: 48000 }, (_, i) => 0.5 * Math.sin((2 * Math.PI * 300 * i) / 48000));
const w = new Resampler(48000);
const frames: Int16Array[] = [];
for (let i = 0; i + 128 <= 48000; i += 128) frames.push(...w.process(x.subarray(i, i + 128)));
console.log(`48000샘플 → 조각 ${frames.length}개 · 조각 하나 ${frames[0].length}샘플 ${frames[0].byteLength}바이트`);
check(w.ratio === 3 && frames[0].length === 320 && frames[0].byteLength === 640 && frames.length === 50, "1초 = 20 ms 조각 50개예요.");

// 4) 실수 → 16비트 정수: 최댓값 32767, 범위 밖은 잘라냄(clipping)
const f1 = new Resampler(16000).process(new Float32Array(400).fill(2));
check(Math.max(...f1[0]) === 32767, "-1 ~ 1을 32767 배로 바꾸고 넘치면 잘라요.");

// 5) 재생 큐와 끼어들기: 다음 시각 = max(지금, 앞 조각 끝) / 끼어들면 큐 비우기
let nextTime = 0;
for (const arrive of [0.0, 0.1, 0.2]) nextTime = Math.max(arrive, nextTime) + 0.5;
check(Math.abs(nextTime - 1.5) < 1e-9, "0.5초 조각 3개는 끊김 없이 1.5초에 끝나요.");
const queue = ["문장1", "문장2", "문장3"];
queue.length = 0;
check(queue.length === 0, "끼어들기에는 재생 큐를 비워요.");
